import java.util.*;
import java.io.*;

public class Prac {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalNumbers = scanner.nextInt();
        int maxBudget = scanner.nextInt();
        int[] numbers = new int[totalNumbers];
        for (int index = 0; index < totalNumbers; index++) {
            numbers[index] = scanner.nextInt();
        }
        int countSegments = 0;
        int startIndex = 0;
        int evenCount = 0, oddCount = 0;
        List<Integer> segmentDiffs = new ArrayList<>();
        for (int i = 0; i < totalNumbers; i++) {
            if (numbers[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            if (evenCount == oddCount && i != totalNumbers - 1) {
                int diff = Math.abs(numbers[i + 1] - numbers[startIndex]);
                segmentDiffs.add(diff);
                startIndex = i + 1;
                evenCount = 0;
                oddCount = 0;
            }
        }
        if (!segmentDiffs.isEmpty()) {
            Collections.sort(segmentDiffs);
            int accumulated = 0;
            for (int i = 0; i < segmentDiffs.size(); i++) {
                accumulated += segmentDiffs.get(i);
                if (accumulated > maxBudget) {
                    countSegments = i;
                    break;
                } else {
                    countSegments = i + 1;
                }
            }
        } else {
            if (totalNumbers > 0) {
                int diff = Math.abs(numbers[0] - numbers[0]);
                if (diff >= maxBudget) {
                    countSegments = 1;
                }
            }
        }
        System.out.println(countSegments);
    }
}
